#include <bits/stdc++.h>using namespace std;using ll = long long; int main() {    ios::sync_with_stdio(false);    cin.tie(nullptr);     int T;    cin >> T;    while (T--) {        ll n, k;        cin >> n >> k;         if (n == k) {            cout << 0 << '\n';            continue;        }         queue<pair<ll, int>> q;        unordered_set<ll> visited;         q.push({n, 0});        visited.insert(n);         int ans = -1;         while (!q.empty()) {            auto [x, time] = q.front();            q.pop();             if (x == k) {                ans = time;                break;            }             if (x < k) continue;              ll a = x / 2;            ll b = (x + 1) / 2;             if (!visited.count(a)) {                visited.insert(a);                q.push({a, time + 1});            }            if (!visited.count(b)) {                visited.insert(b);                q.push({b, time + 1});            }        }         cout << ans << '\n';    }    return 0;}